<script setup lang="ts">
import {computed} from 'vue'
import {useWorkbench} from '../stores/workbench'
import {progress,type Project,stages} from '../lib/domain'
import Icon from './Icon.vue'
const props=defineProps<{project:Project}>(),store=useWorkbench()
const done=computed(()=>progress(props.project));const current=computed(()=>store.catalog.nodes.find(n=>!['COMPLETED','SKIPPED'].includes(props.project.nodes[n.id]?.status)))
</script>
<template><RouterLink :to="'/projects/'+project.id" class="project-card"><div :class="['poster',project.poster]"><span class="poster-mark">FRAME ORIGINAL</span><span class="sample-tag" v-if="project.sample">示例</span><template v-if="project.poster==='sage'"><div class="poster-sun"/><div class="poster-orbit"/><div class="poster-type sage-type">LESS,<br> BUT BETTER<span>把时间，留给重要的事。</span></div><span class="poster-bottom">A NOTE ON LIVING INTENTIONALLY</span></template><template v-else-if="project.poster==='apricot'"><div class="poster-type studio-type">STUDIO<br>OF ONE<span>一个人，也能认真创作。</span></div><span class="poster-sticker"><Icon name="ArrowUpRight" :size="28"/></span><span class="poster-bottom">IDEA → MAKE → SHARE</span></template><template v-else><div class="poster-window"><span/><span/><span/><div class="poster-code">hello, possibility.<br><b>make something</b><br>that matters_</div></div><div class="poster-type blue-type">日常里的<br><em>一点 AI</em></div><span class="poster-bottom">A PRACTICAL FIELD GUIDE</span></template><span class="poster-open"><Icon name="ArrowUpRight" :size="18"/></span></div><div class="project-card-body"><div class="project-meta"><span class="stage-label"><i/>{{current?stages[current.stage]:'已完成'}}</span><span class="muted small">{{project.template==='AI_STORY'?'AI 故事':project.template==='REAL_PERSON'?'真人口播':'录屏解说'}}</span></div><h3>{{project.title}}</h3><p>{{current?`${current.id} · ${current.name}`:'全部节点已完成，去看看复盘结果'}}</p><div class="progress-line"><span :style="{transform:'scaleX('+done/store.catalog.nodes.length+')'}"/></div><div class="project-card-foot"><span>{{done}}<span class="muted"> / {{store.catalog.nodes.length}} 个节点</span></span><div class="platforms"><span v-if="project.platforms.includes('DOUYIN')" title="抖音">抖</span><span v-if="project.platforms.includes('XIAOHONGSHU')" title="小红书">红</span></div></div></div></RouterLink></template>
